// Otomatik üretildi (DKAB-Kitap-Hatti/pasaparola/mamoste.py). Elle düzenleme.
// Yer tutucular: /*__HAVUZ__*/ __BASLIK__ __ALT__ __IMZA__ __ANAHTAR__ (ActivityPlayScreen doldurur).
export default "<!doctype html>\n<html lang=\"tr\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>__BASLIK__</title>\n<style>\n:root{--zemin:#0B1020;--kart:#141B33;--yazi:#F1F5F9;--soluk:#94A3B8;--mavi:#2563EB;--yesil:#16A34A;--kirmizi:#DC2626;--sari:#F59E0B;--altin:#FBBF24}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%;background:radial-gradient(circle at 50% 40%,#1E2A55 0%,#0B1020 70%);color:var(--yazi);font-family:\"Helvetica Neue\",Arial,sans-serif;overflow:hidden}\nbutton{font-family:inherit;cursor:pointer}\n.ekran{display:none;position:absolute;inset:0}.ekran.aktif{display:flex}\n/* Başlangıç */\n#giris{flex-direction:column;align-items:center;justify-content:center;gap:2.2vh;text-align:center;padding:2vh 4vw}\n#giris h1{font-size:9vh;margin:0;letter-spacing:.4vh;background:linear-gradient(180deg,#FDE68A,#F59E0B);-webkit-background-clip:text;color:transparent;font-weight:900}\n.alt{font-size:2.6vh;color:#CBD5E1}\n.imza{font-size:2.2vh;color:var(--altin);background:rgba(251,191,36,.08);border:1px solid rgba(251,191,36,.35);border-radius:99px;padding:.8vh 2vw}\n.panel{background:rgba(20,27,51,.85);border:1px solid #2B3763;border-radius:2vh;padding:2vh 3vw;max-width:110vh}\n.kural{font-size:2.3vh;line-height:1.5;text-align:left;color:#E2E8F0}.kural b{color:var(--altin)}\n.secenek{display:flex;gap:1.2vw;justify-content:center;align-items:center;flex-wrap:wrap}\n.secenek .etk{font-size:2.3vh;color:var(--soluk)}\n.sure{font-size:2.6vh;font-weight:800;padding:1vh 1.6vw;border-radius:1.4vh;border:2px solid #334155;background:#111827;color:#E5E7EB}\n.sure.sec{background:var(--mavi);border-color:#93C5FD}\n.buyuk{font-size:3.6vh;font-weight:900;padding:1.6vh 5vw;border:none;border-radius:2vh;background:linear-gradient(180deg,#FCD34D,#F59E0B);color:#111;box-shadow:0 .8vh 0 #B45309}\n.buyuk:active{transform:translateY(.4vh);box-shadow:0 .4vh 0 #B45309}\n/* Dik ekran (telefon): harf çemberi üstte, ortasında süre/sayaç/kural; soru, şıklar ve PAS çemberin altında. */\nbody.dik #oyun{flex-direction:column;justify-content:flex-start;padding-top:max(12vh,64px);gap:2vh}\nbody.dik #cember{width:94vw;height:94vw;flex:none}\nbody.dik .harf{width:9%;font-size:4.2vw;border-width:.6vw}\nbody.dik #orta{width:68%;gap:1.4vw}\nbody.dik #ust{gap:2vw;flex-wrap:wrap}\nbody.dik #saat{font-size:10vw;min-width:0}\nbody.dik .sayac{font-size:3.4vw;padding:.8vw 2.4vw}\nbody.dik #kural{font-size:3.8vw;padding:1vw 3vw}\n#alt{display:none}\nbody.dik #alt{display:flex;flex-direction:column;align-items:center;gap:1.4vh;width:92vw}\nbody.dik #ipucu{font-size:4.6vw;min-height:0;padding:3vw 4vw;border-radius:3vw}\nbody.dik #siklar{width:100%;gap:1.2vh}\nbody.dik .sik{font-size:4.6vw;padding:2.4vw 3vw;gap:3vw;border-radius:3vw}\nbody.dik .sik .hrf{width:8vw;height:8vw}\nbody.dik #pasBtn{font-size:4.2vw;padding:2vw 7vw}\nbody.dik .ipucuKisayol{display:none}\nbody.dik #oyuncuEtiket{font-size:3.6vw}\nbody.dik #durBtn,body.dik #sesBtn{font-size:3.4vw;padding:1.6vw 2.6vw}\n/* Oyun */\n#oyun{align-items:center;justify-content:center}\n#cember{position:relative;width:min(96vh,96vw);height:min(96vh,96vw)}\n.harf{position:absolute;width:7.6%;aspect-ratio:1;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:min(3.6vh,3.6vw);color:#fff;text-shadow:0 .2vh .4vh rgba(0,0,0,.45);background:radial-gradient(circle at 35% 30%,#60A5FA,#1D4ED8 70%);border:.4vh solid #BFDBFE;box-shadow:0 0 1.2vh rgba(59,130,246,.55);transform:translate(-50%,-50%);transition:all .25s}\n.harf.simdi{transform:translate(-50%,-50%) scale(1.3);background:#FFFFFF;color:#1D4ED8;text-shadow:none;border-color:#93C5FD;box-shadow:0 0 3vh #fff}\n.harf.dogru{background:linear-gradient(180deg,#22C55E,#15803D)!important;border-color:#BBF7D0;box-shadow:0 0 1.2vh rgba(34,197,94,.6)}\n.harf.yanlis{background:linear-gradient(180deg,#EF4444,#B91C1C)!important;border-color:#FECACA;box-shadow:0 0 1.2vh rgba(239,68,68,.6)}\n.harf.pas{background:linear-gradient(180deg,#FB923C,#EA580C)!important;border-color:#FED7AA;box-shadow:0 0 1.2vh rgba(234,88,12,.6)}\n.harf.dogru,.harf.yanlis,.harf.pas{--r:transparent}\n#orta{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:66%;display:flex;flex-direction:column;align-items:center;gap:1.6vh;text-align:center}\n#ust{display:flex;gap:2vw;align-items:center;justify-content:center}\n#saat{font-size:6.5vh;font-weight:900;font-variant-numeric:tabular-nums;color:#fff;min-width:14vh}\n#saat.az{color:#F87171;animation:nabiz 1s infinite}\n@keyframes nabiz{50%{opacity:.45}}\n.sayac{font-size:2.8vh;font-weight:900;padding:.8vh 1.4vw;border-radius:99px;white-space:nowrap}\n#dSay{background:#16A34A;color:#fff;border:.3vh solid #fff}\n#ySay{background:#DC2626;color:#fff;border:.3vh solid #fff}\n#kural{font-size:2.6vh;font-weight:900;color:#111;background:linear-gradient(180deg,#FDE68A,#F59E0B);padding:.6vh 1.8vw;border-radius:99px;letter-spacing:.2vh}\n#ipucu{font-size:3vh;line-height:1.4;font-weight:600;min-height:13vh;display:flex;align-items:center;justify-content:center;width:100%;background:#FFFFFF;color:#1A1A2E;border:.4vh solid #E0E0E0;border-radius:2vh;padding:1.8vh 2vw;box-shadow:0 .6vh 1.6vh rgba(0,0,0,.35)}\n#siklar{display:flex;flex-direction:column;gap:1.2vh;width:80%}\n.sik{display:flex;align-items:center;gap:1.2vw;font-size:2.9vh;text-align:left;font-weight:600;padding:1.5vh 1.4vw;border-radius:1.6vh;border:.4vh solid #E0E0E0;background:#FFFFFF;color:#1A1A2E;box-shadow:0 .4vh 1vh rgba(0,0,0,.25)}\n.sik .hrf{flex:none;width:5vh;height:5vh;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:900;color:#fff;background:#1D4ED8}\n.sik:nth-child(2) .hrf{background:#EA580C}\n.sik.dogru,.sik.yanlis{color:#fff}.sik.dogru .hrf,.sik.yanlis .hrf{background:rgba(255,255,255,.25)}\n.sik:hover{border-color:#F59E0B}\n.sik.dogru{background:#22C55E;border-color:#22C55E}.sik.yanlis{background:#EF4444;border-color:#EF4444}\n#pasBtn{font-size:2.6vh;font-weight:900;padding:1.2vh 3vw;border-radius:99px;border:.3vh solid #CBD5E1;background:#334155;color:#fff;letter-spacing:.3vh}\n.ipucuKisayol{font-size:1.6vh;color:var(--soluk)}\n#durBtn{position:absolute;top:2vh;right:2vw;font-size:2vh;padding:1vh 1.4vw;border-radius:1vh;border:1px solid #475569;background:#111827;color:#E5E7EB}\n/* Sonuç */\n#sonuc{flex-direction:column;align-items:center;justify-content:center;gap:2vh;text-align:center;padding:2vh}\n#sonuc h2{font-size:6vh;margin:0}\n#yildiz{font-size:9vh;letter-spacing:1vh}\n#ozet{font-size:3vh}\n#liste{max-height:42vh;overflow:auto;font-size:2.1vh;text-align:left;width:min(110vh,92vw)}\n#liste div{padding:.6vh 1vw;border-bottom:1px solid #1F2A4D}\n#liste b{display:inline-block;width:4vh;text-align:center;border-radius:50%;margin-right:1vw}\n.sinifBtn{font-size:2.8vh;font-weight:900;padding:1.2vh 2vw;border-radius:1.4vh;border:.3vh solid transparent;color:#fff}\n.sinifBtn.sec{outline:.45vh solid #fff;outline-offset:.3vh;transform:scale(1.06)}\n.rastgele{font-size:2.6vh;font-weight:700;padding:1.2vh 1.8vw;border-radius:1.4vh;border:2px solid rgba(255,255,255,.35);background:transparent;color:#E5E7EB}\n.adSec{font-size:3vh;font-weight:900;padding:1.6vh 3vw;border-radius:1.8vh;border:none;color:#1C1C1E;background:linear-gradient(135deg,#FFE27A,#FFC93C 55%,#F59E0B);box-shadow:0 0 0 .35vh rgba(255,201,60,.35),0 .7vh 1.8vh rgba(0,0,0,.35)}\n#yarismaci{font-size:3vh;font-weight:900;color:var(--altin);min-height:4vh}\n#modal{position:fixed;inset:0;background:rgba(0,0,0,.72);display:none;align-items:center;justify-content:center;z-index:9}\n#modal.acik{display:flex}\n#modalIc{background:#141B33;border:1px solid #334155;border-radius:2vh;padding:2.4vh 2.4vw;max-width:94vw;max-height:90vh;overflow:auto;text-align:center}\n#modalIc h2{margin:0 0 1.6vh;font-size:3.6vh}\n.adlar{display:grid;grid-template-columns:repeat(auto-fill,minmax(26vh,1fr));gap:1vh;margin-bottom:1.6vh}\n.adlar button{font-size:2.3vh;font-weight:700;padding:1.1vh 1vw;border-radius:1.2vh;border:2px solid #334155;background:#1E293B;color:#fff;text-align:left}\n.adlar button b{color:var(--altin);margin-right:.6vw}\n.adlar button.oldu{opacity:.45}\n.cark{font-size:6vh;font-weight:900;color:var(--altin);min-height:9vh;margin:2vh 0}\n#oyuncuEtiket{position:absolute;top:2vh;left:2vw;font-size:2.6vh;font-weight:800;padding:1vh 1.4vw;border-radius:1.2vh;background:rgba(251,191,36,.12);border:1px solid rgba(251,191,36,.5);color:var(--altin)}\n#sesBtn{position:absolute;top:2vh;left:2vw;font-size:2vh;padding:1vh 1.4vw;border-radius:1vh;border:1px solid #475569;background:#111827;color:#E5E7EB}\n#konfeti{position:fixed;inset:0;pointer-events:none;z-index:8}\n#carpi{position:fixed;inset:0;display:flex;align-items:center;justify-content:center;pointer-events:none;z-index:8;opacity:0}\n#carpi span{font-size:42vh;font-weight:900;color:#EF4444;text-shadow:0 0 6vh rgba(239,68,68,.8),0 0 1vh #fff;line-height:1}\n#carpi.goster{animation:carpiAnim 1.1s ease-out}\n@keyframes carpiAnim{0%{opacity:0;transform:scale(.3) rotate(-20deg)}18%{opacity:1;transform:scale(1.15) rotate(5deg)}30%{transform:scale(1) rotate(0)}38%{transform:translateX(-3vh)}46%{transform:translateX(3vh)}54%{transform:translateX(-2vh)}62%{transform:translateX(0);opacity:1}100%{opacity:0;transform:scale(1.05)}}\n.kucuk{font-size:2.4vh;font-weight:800;padding:1.2vh 2.4vw;border-radius:1.4vh;border:1px solid #475569;background:#1E293B;color:#fff}\n</style></head><body>\n\n<section id=\"giris\" class=\"ekran aktif\">\n  <h1>PASAPAROLA</h1>\n  <div class=\"alt\">__ALT__</div>\n  __IMZA__\n  <div class=\"panel kural\">\n    <b>Nasıl oynanır?</b><br>\n    • Her harfte bir ipucu gelir. Cevap ya <b>o harfle başlar</b> ya da <b>içinde o harf geçer</b>.<br>\n    • İki seçenekten doğru olanı seç. Doğru cevap <span style=\"color:#4ADE80\">yeşil</span>, yanlış cevap <span style=\"color:#F87171\">kırmızı</span> yanar.<br>\n    • Bilmiyorsan <b>PAS</b> de: harf turuncuya döner, tur sonunda yeniden sorulur.<br>\n    • <b>3 yanlış hakkı</b> var: 3. yanlışta yarışma biter. <b>3 pas hakkı</b> var: haklar bitince PAS kapanır.<br>• Süre bitince, 3. yanlışta ya da bütün harfler cevaplanınca yarışma biter; en çok doğruyu yapan kazanır.<br>\n    • Klavye: <b>A</b> / <b>B</b> seçenekler, <b>Boşluk</b> pas.\n  </div>\n  <div style=\"display:flex;gap:2vw;align-items:center;justify-content:center;flex-wrap:wrap\">\n  <div class=\"panel\" style=\"display:flex;flex-direction:column;gap:1.6vh;align-items:center\">\n    <div class=\"secenek\" id=\"sinifSatir\"><span class=\"etk\">Sınıf Seç</span><button class=\"rastgele\" onclick=\"rastgeleSec()\">🎲 Rastgele</button><span id=\"siniflar\"></span></div>\n    <div class=\"secenek\"><button class=\"adSec\" id=\"adBtn\" onclick=\"ogrenciSec()\">👤 Adını Seç</button></div>\n    <div id=\"listeYok\" style=\"display:none;font-size:2vh;color:#94A3B8\"></div>\n  </div>\n  <button class=\"buyuk\" onclick=\"basla()\" style=\"font-size:3vh;padding:1.6vh 3vw;border-radius:1.8vh;align-self:center\">▶ BAŞLA</button>\n  </div>\n  <div class=\"secenek\"><span class=\"etk\">Toplam süre</span>\n    <button class=\"sure\" data-s=\"150\">2,5 dk</button><button class=\"sure sec\" data-s=\"200\">3 dk 20 sn</button><button class=\"sure\" data-s=\"240\">4 dk</button></div>\n  <div id=\"kalanBilgi\" style=\"font-size:2.1vh;color:#CBD5E1\"></div>\n  <div class=\"secenek\"><button class=\"kucuk\" onclick=\"kayitlar()\">🏆 Geçmiş</button><button class=\"kucuk\" onclick=\"hafizaSifirla()\">🔄 Soruları Sıfırla</button></div>\n</section>\n<canvas id=\"konfeti\"></canvas><div id=\"carpi\"><span>✖</span></div>\n<div id=\"modal\" onclick=\"if(event.target===this)modalKapat()\"><div id=\"modalIc\"></div></div>\n\n<section id=\"oyun\" class=\"ekran\">\n  <div id=\"oyuncuEtiket\"></div><button id=\"sesBtn\" style=\"top:9vh\" onclick=\"sesAcik=!sesAcik;this.textContent=sesAcik?'🔊 Ses':'🔇 Ses'\">🔊 Ses</button><button id=\"durBtn\" onclick=\"duraklat()\">⏸ Duraklat</button>\n  <div id=\"cember\">\n    <div id=\"orta\">\n      <div id=\"ust\"><span class=\"sayac\" id=\"dSay\">0 Doğru</span><span id=\"saat\">0:00</span><span class=\"sayac\" id=\"ySay\">0 Yanlış · 3 hak</span></div>\n      <div id=\"kural\"></div>\n      <div id=\"ipucu\"></div>\n      <div id=\"siklar\"><button class=\"sik\" onclick=\"cevap(0)\"></button><button class=\"sik\" onclick=\"cevap(1)\"></button></div>\n      <button id=\"pasBtn\" onclick=\"pas()\">PAS</button>\n      <div class=\"ipucuKisayol\">A / B seçenek · Boşluk = pas</div>\n    </div>\n  </div>\n  <div id=\"alt\"></div>\n</section>\n\n<section id=\"sonuc\" class=\"ekran\">\n  <h2 id=\"sonBaslik\"></h2>\n  <div id=\"yildiz\"></div>\n  <div id=\"ozet\"></div>\n  <div id=\"liste\" class=\"panel\"></div>\n  <div class=\"secenek\"><button class=\"buyuk\" onclick=\"goster('giris')\">🔁 YENİ YARIŞMA</button></div>\n</section>\n\n\n<script>// Gerçek alkış kaydı: “applause-2” — Sandermotions (freesound.org/people/Sandermotions/sounds/277021), CC0 (kamu malı).\n// De Doelen konser salonu, Rotterdam. 16 kHz 8 bit mono WAV, base64 (tools/etkinlik/pasaparola_duzelt.py).\nconst ALKIS_WAV='';\n</script>\n<script>\n// Sorular yalnız 10. sınıf DKAB ders kitabı 1. ünite ANA METNİNDEN (İslam'da Varlık ve Bilgi).\n// [harf, \"başlar\"|\"içinde\", ipucu, doğru, yanlış]  — iki seçenek de aynı harf kuralına uyar.\n/*__HAVUZ__*/\nconst HARFLER=Object.keys(HAVUZ);\n// Her yarışmada her harften bir soru seçilir: önce bu sınıfta hiç gösterilmemiş olanlar.\n// Baştaki harflerde kolay, ortada orta, sonda zor sorular tercih edilir (kolaydan zora).\n// Yalnız EKRANDA GÖSTERİLEN soru \"görüldü\" sayılır; elenen öğrencinin göremediği harfler sonrakilere kalır.\nconst HAFIZA=()=>'pasaparola_gorulen:__ANAHTAR__:'+(sinifNo>=0&&LISTE[sinifNo]?LISTE[sinifNo].ad:'genel');\nfunction gorulen(){try{return JSON.parse(localStorage.getItem(HAFIZA())||'{}')}catch(e){return {}}}\nfunction gorulduYap(id){try{const g=gorulen();g[id]=Date.now();localStorage.setItem(HAFIZA(),JSON.stringify(g))}catch(e){}}\nlet SORULAR=[];\nfunction sorulariSec(){const g=gorulen(),n=HARFLER.length;\n  SORULAR=HARFLER.map((h,i)=>{const hedef=i<n/3?1:i<2*n/3?2:3;\n    const l=HAVUZ[h].map((q,k)=>({q,id:h+k,t:g[h+k]||0}));\n    l.sort((a,b)=>(a.t>0)-(b.t>0)||a.t-b.t||Math.abs(a.q[4]-hedef)-Math.abs(b.q[4]-hedef)||Math.random()-.5);\n    const x=l[0];return [h,x.q[0]==='b'?'başlar':'içinde',x.q[1],x.q[2],x.q[3],x.id]})}\nfunction kalanSoru(){const g=gorulen();return HARFLER.reduce((t,h)=>t+HAVUZ[h].filter((_,k)=>!g[h+k]).length,0)}\nfunction hafizaSifirla(){if(!confirm('Bu sınıfın gösterilen soru hafızası silinsin mi? Bütün sorular yeniden en baştan sorulabilir.'))return;try{localStorage.removeItem(HAFIZA())}catch(e){}sinifCiz()}\n\nlet sure=200,kalan=0,zam=null,durdu=false,kuyruk=[],simdi=-1,durum={},kilit=false,ses=null;\ndocument.querySelectorAll('.sure').forEach(b=>b.onclick=()=>{document.querySelectorAll('.sure').forEach(x=>x.classList.remove('sec'));b.classList.add('sec');sure=+b.dataset.s});\nfunction goster(id){document.querySelectorAll('.ekran').forEach(e=>e.classList.toggle('aktif',e.id===id))}\n// ── YERLEŞİM ── dik ekranda (telefon) soru, şıklar ve PAS çemberin altına taşınır.\nfunction yerlesim(){const dik=innerHeight>innerWidth*1.15;document.body.classList.toggle('dik',dik);\n  const hedef=document.getElementById(dik?'alt':'orta');['ipucu','siklar','pasBtn'].forEach(id=>hedef.appendChild(document.getElementById(id)));\n  const k=document.querySelector('.ipucuKisayol');if(k)document.getElementById('orta').appendChild(k)}\naddEventListener('resize',yerlesim);addEventListener('load',yerlesim);\nfunction cemberKur(){const c=document.getElementById('cember');c.querySelectorAll('.harf').forEach(h=>h.remove());const n=SORULAR.length;\n  SORULAR.forEach((q,i)=>{const a=-Math.PI/2+i*2*Math.PI/n;const d=document.createElement('div');d.className='harf';d.id='h'+i;d.textContent=q[0];d.style.left=(50+45.5*Math.cos(a))+'%';d.style.top=(50+45.5*Math.sin(a))+'%';c.appendChild(d)})}\n// ── SES ── (Web Audio; alkış gerçek kayıt ses_alkis.js)\nlet ac=null,alkisKayit=null;\nfunction sesBaslat(){try{ac=ac||new (window.AudioContext||window.webkitAudioContext)();if(ac.state==='suspended')ac.resume();\n  if(!alkisKayit&&typeof ALKIS_WAV!=='undefined'){alkisKayit=1;fetch('data:audio/wav;base64,'+ALKIS_WAV).then(r=>r.arrayBuffer()).then(a=>ac.decodeAudioData(a,x=>alkisKayit=x,()=>alkisKayit=null)).catch(()=>alkisKayit=null)}}catch(e){}}\nfunction ton(f,t=.15,tip='sine',v=.18,gec=0,f2){if(!ac)return;const b=ac.currentTime+gec,o=ac.createOscillator(),g=ac.createGain();o.type=tip;o.frequency.setValueAtTime(f,b);if(f2)o.frequency.exponentialRampToValueAtTime(f2,b+t);g.gain.setValueAtTime(.0001,b);g.gain.exponentialRampToValueAtTime(v,b+.015);g.gain.exponentialRampToValueAtTime(.0001,b+t);o.connect(g);g.connect(ac.destination);o.start(b);o.stop(b+t+.02)}\nfunction alkis(sure=3,g=.6){if(!ac||!alkisKayit||alkisKayit===1)return;const s=ac.createBufferSource(),v=ac.createGain(),b=ac.currentTime,uz=Math.min(sure,alkisKayit.duration);s.buffer=alkisKayit;v.gain.setValueAtTime(g,b);v.gain.setValueAtTime(g,b+Math.max(.1,uz-.8));v.gain.linearRampToValueAtTime(.0001,b+uz);s.connect(v);v.connect(ac.destination);s.start(b,.45,uz+.05)}\nconst SES={\n dogru:()=>{ton(784,.12,'triangle',.2);ton(1046,.22,'triangle',.2,.1);ton(1318,.3,'sine',.12,.2);alkis(1.8,.5)},\n yanlis:()=>{ton(140,.22,'square',.16);ton(140,.22,'sawtooth',.12);ton(118,.45,'square',.16,.26);ton(118,.45,'sawtooth',.12,.26)},\n pas:()=>{ton(520,.09,'square',.07);ton(390,.12,'square',.07,.09)},\n harf:()=>ton(1200,.05,'sine',.06),\n tik:()=>ton(1500,.04,'square',.05),\n son10:()=>{ton(880,.07,'square',.07)},\n basla:()=>{[392,523,659,784].forEach((f,i)=>ton(f,.18,'triangle',.18,i*.12));},\n bitis:()=>{ton(523,.2,'sawtooth',.12);ton(392,.25,'sawtooth',.12,.2);ton(262,.6,'sawtooth',.12,.45)},\n zafer:()=>{[523,659,784,1046,1318].forEach((f,i)=>ton(f,.25,'triangle',.18,i*.13));alkis(4)},\n sec:()=>ton(700,.1,'triangle',.14)\n};\nlet sesAcik=true;function cal(n){if(sesAcik){sesBaslat();SES[n]&&SES[n]()}}\nconst bip=()=>{};\n// ── KONFETİ ve ÇARPI ──\nconst kc=document.getElementById('konfeti'),kx=kc.getContext('2d');let parca=[],kAnim=null;\nfunction konfeti(n=140){kc.width=innerWidth;kc.height=innerHeight;const R=['#22C55E','#FBBF24','#3B82F6','#EF4444','#A855F7','#F97316','#14B8A6','#fff'];\n  for(let i=0;i<n;i++){const sol=i%2===0;parca.push({x:sol?0:kc.width,y:kc.height*.75,vx:(sol?1:-1)*(6+Math.random()*12),vy:-(10+Math.random()*16),g:.42,w:6+Math.random()*9,h:8+Math.random()*12,a:Math.random()*6,va:(Math.random()-.5)*.4,c:R[i%R.length],o:1})}\n  if(!kAnim)kAnim=requestAnimationFrame(kAdim)}\nfunction kAdim(){kx.clearRect(0,0,kc.width,kc.height);parca=parca.filter(p=>p.o>0&&p.y<kc.height+40);\n  for(const p of parca){p.vy+=p.g;p.vx*=.99;p.x+=p.vx;p.y+=p.vy;p.a+=p.va;if(p.vy>4)p.o-=.012;kx.save();kx.globalAlpha=Math.max(0,p.o);kx.translate(p.x,p.y);kx.rotate(p.a);kx.fillStyle=p.c;kx.fillRect(-p.w/2,-p.h/2,p.w,p.h*Math.abs(Math.cos(p.a*1.7)));kx.restore()}\n  kAnim=parca.length?requestAnimationFrame(kAdim):(kx.clearRect(0,0,kc.width,kc.height),null)}\nfunction carpiGoster(){const c=document.getElementById('carpi');c.classList.remove('goster');void c.offsetWidth;c.classList.add('goster')}\n\n// ── SINIF VE ÖĞRENCİ (ogrenciler.js; yalnız 10. sınıflar) ──\nconst LISTE=((window.OGRENCI_LISTESI&&window.OGRENCI_LISTESI.siniflar)||[]).filter(s=>String(s.ad).startsWith('10')&&s.ogrenciler&&s.ogrenciler.length)\n  .map(s=>({ad:s.ad,og:s.ogrenciler.map(o=>typeof o==='string'?{ad:o,no:''}:{ad:o.ad,no:o.no||''})}));\nconst RENK=['#2563EB','#16A34A','#EA580C','#DB2777','#7C3AED','#0891B2','#CA8A04','#DC2626'];\nlet sinifNo=LISTE.length===1?0:-1,oyuncu=null;const oynayan={};\nconst esc=t=>String(t).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nfunction modal(h){document.getElementById('modalIc').innerHTML=h;document.getElementById('modal').classList.add('acik')}\nfunction modalKapat(){document.getElementById('modal').classList.remove('acik');clearInterval(carkZ)}\nfunction sinifCiz(){const e=document.getElementById('siniflar');if(!LISTE.length){document.getElementById('adBtn').closest('.panel').style.display='none';return}\n  document.getElementById('kalanBilgi').textContent=`Soru havuzu: ${HARFLER.length} harf × 5 = ${HARFLER.length*5} soru · Bu sınıfta henüz sorulmamış: ${kalanSoru()}`;e.innerHTML=LISTE.map((s,i)=>`<button class=\"sinifBtn${i===sinifNo?' sec':''}\" style=\"background:${RENK[i%RENK.length]}\" onclick=\"sinifSec(${i})\">${esc(s.ad)}</button>`).join(' ');\n  const b=document.getElementById('adBtn');b.textContent=oyuncu?'👤 '+(oyuncu.no?oyuncu.no+' · ':'')+oyuncu.ad:'👤 Adını Seç';\n  b.style.background=sinifNo>=0&&oyuncu?RENK[sinifNo%RENK.length]:'';b.style.color=sinifNo>=0&&oyuncu?'#fff':''}\nfunction sinifSec(i){sinifNo=i;oyuncu=null;cal('sec');sinifCiz()}\nfunction sinifGerek(){if(!LISTE.length)return false;if(sinifNo<0){alert('Önce sınıfı seçin.');return false}return true}\nfunction ogrenciSec(){if(!sinifGerek())return;const s=LISTE[sinifNo],y=oynayan[s.ad]||new Set();\n  modal(`<h2>👤 ${esc(s.ad)} · Adını seç</h2><div class=\"adlar\">${s.og.map((o,i)=>`<button class=\"${y.has(o.ad)?'oldu':''}\" onclick=\"adAta(${i})\">${o.no?`<b>${esc(o.no)}</b>`:''}${esc(o.ad)}</button>`).join('')}</div><button class=\"kucuk\" onclick=\"modalKapat()\">Kapat</button>`)}\nfunction adAta(i){oyuncu=LISTE[sinifNo].og[i];modalKapat();cal('sec');sinifCiz()}\nlet carkZ=null;\nfunction rastgeleSec(){if(!sinifGerek())return;const s=LISTE[sinifNo],y=oynayan[s.ad]||(oynayan[s.ad]=new Set());let h=s.og.filter(o=>!y.has(o.ad));if(!h.length){y.clear();h=s.og.slice()}\n  const sec=h[Math.floor(Math.random()*h.length)];const yaz=o=>(o.no?o.no+' · ':'')+o.ad;\n  modal(`<h2>🎲 ${esc(s.ad)} · Yarışmacı seçiliyor…</h2><div class=\"cark\" id=\"cark\"></div><div id=\"carkD\"></div>`);let n=0;clearInterval(carkZ);\n  carkZ=setInterval(()=>{const e=document.getElementById('cark');if(!e)return clearInterval(carkZ);if(++n<24){e.textContent=yaz(s.og[Math.floor(Math.random()*s.og.length)]);cal('tik')}\n    else{clearInterval(carkZ);e.textContent='🎉 '+yaz(sec);oyuncu=sec;cal('zafer');sinifCiz();document.getElementById('carkD').innerHTML='<button class=\"buyuk\" onclick=\"modalKapat()\">TAMAM</button>'}},90)}\n// ── KAYITLAR (bu bilgisayarın tarayıcısında) ──\nconst KAYIT='pasaparola_kayit:__ANAHTAR__';\nfunction kayitOku(){try{return JSON.parse(localStorage.getItem(KAYIT)||'[]')}catch(e){return []}}\nfunction kayitYaz(k){try{const a=kayitOku();a.push(k);localStorage.setItem(KAYIT,JSON.stringify(a.slice(-300)))}catch(e){}}\nfunction kayitlar(){const a=kayitOku().slice().reverse(),s=sinifNo>=0?LISTE[sinifNo].ad:null,l=s?a.filter(k=>k.sinif===s):a;\n  modal(`<h2>🏆 Geçmiş${s?' · '+esc(s):''}</h2><div style=\"text-align:left;font-size:2.2vh;max-height:60vh;overflow:auto\">${l.length?l.map(k=>`<div style=\"padding:.6vh 0;border-bottom:1px solid #1F2A4D\">${'★'.repeat(k.y)+'☆'.repeat(3-k.y)} <b>${esc(k.ad||'İsimsiz')}</b> ${k.sinif?'('+esc(k.sinif)+')':''} — ${k.d} doğru, ${k.yn} yanlış · <span style=\"color:#94A3B8\">${new Date(k.t).toLocaleDateString('tr-TR')}</span></div>`).join(''):'Henüz kayıt yok.'}</div><button class=\"kucuk\" onclick=\"modalKapat()\">Kapat</button>`)}\nsinifCiz();\n\nfunction basla(){sorulariSec();if(LISTE.length&&sinifNo>=0&&!oyuncu){alert('Önce adını seç (ya da 🎲 Rastgele).');return}sesBaslat();cal('basla');document.getElementById('oyuncuEtiket').textContent=oyuncu?'👤 '+oyuncu.ad+(sinifNo>=0?' · '+LISTE[sinifNo].ad:''):'';if(oyuncu&&sinifNo>=0)(oynayan[LISTE[sinifNo].ad]||(oynayan[LISTE[sinifNo].ad]=new Set())).add(oyuncu.ad);cemberKur();kuyruk=SORULAR.map((_,i)=>i);durum={};pasSay=0;pasYaz();kalan=sure;durdu=false;goster('oyun');saatYaz();sayacYaz();clearInterval(zam);zam=setInterval(tik,1000);sonraki()}\nfunction tik(){if(durdu)return;kalan--;saatYaz();if(kalan<=10&&kalan>0)cal('son10');if(kalan<=0)bitir()}\nfunction saatYaz(){const s=document.getElementById('saat');s.textContent=Math.floor(kalan/60)+':'+String(kalan%60).padStart(2,'0');s.classList.toggle('az',kalan<=20)}\nfunction sayacYaz(){const d=Object.values(durum).filter(x=>x==='d').length,y=Object.values(durum).filter(x=>x==='y').length;document.getElementById('dSay').textContent=d+' Doğru';document.getElementById('ySay').textContent=y+' Yanlış · '+(YANLIS_HAK-y)+' hak'}\nfunction sonraki(){document.querySelectorAll('.harf').forEach(h=>h.classList.remove('simdi'));if(!kuyruk.length)return bitir();simdi=kuyruk.shift();const q=SORULAR[simdi];\n  const h=document.getElementById('h'+simdi);h.classList.remove('pas');h.classList.add('simdi');cal('harf');gorulduYap(q[5]);\n  document.getElementById('kural').textContent=q[1]==='başlar'?`“${q[0]}” İLE BAŞLAR`:`İÇİNDE “${q[0]}” VAR`;\n  document.getElementById('ipucu').textContent=q[2];\n  const s=Math.random()<.5?[q[3],q[4]]:[q[4],q[3]];document.querySelectorAll('.sik').forEach((b,i)=>{b.innerHTML=`<span class=\"hrf\">${'AB'[i]}</span><span>${esc(s[i])}</span>`;b.dataset.c=s[i];b.className='sik'});kilit=false}\nfunction cevap(i){if(kilit||durdu||simdi<0)return;kilit=true;const q=SORULAR[simdi],b=document.querySelectorAll('.sik')[i],ok=b.dataset.c===q[3];\n  durum[simdi]=ok?'d':'y';document.getElementById('h'+simdi).classList.remove('simdi');document.getElementById('h'+simdi).classList.add(ok?'dogru':'yanlis');\n  b.classList.add(ok?'dogru':'yanlis');if(!ok)document.querySelectorAll('.sik').forEach(x=>{if(x.dataset.c===q[3])x.classList.add('dogru')});\n  cal(ok?'dogru':'yanlis');ok?konfeti():carpiGoster();sayacYaz();const yn=Object.values(durum).filter(x=>x==='y').length;setTimeout(yn>=YANLIS_HAK?()=>bitir('yanlis'):sonraki,ok?1300:1500)}\nconst YANLIS_HAK=3,PAS_HAK=3;let pasSay=0;\nfunction pasYaz(){const b=document.getElementById('pasBtn');const k=PAS_HAK-pasSay;b.textContent=k>0?`PAS (${k} hak)`:'PAS hakkı bitti';b.disabled=k<=0;b.style.opacity=k>0?1:.4}\nfunction pas(){if(kilit||durdu||simdi<0||pasSay>=PAS_HAK)return;kilit=true;pasSay++;pasYaz();const h=document.getElementById('h'+simdi);h.classList.remove('simdi');h.classList.add('pas');kuyruk.push(simdi);cal('pas');setTimeout(sonraki,250)}\nfunction duraklat(){durdu=!durdu;document.getElementById('durBtn').textContent=durdu?'▶ Devam':'⏸ Duraklat';document.getElementById('orta').style.opacity=durdu?.15:1}\nfunction bitir(neden){clearInterval(zam);simdi=-1;const d=Object.values(durum).filter(x=>x==='d').length,y=Object.values(durum).filter(x=>x==='y').length,n=SORULAR.length,b=n-d-y;\n  const yz=d>=24?3:d>=18?2:d>=12?1:0;document.getElementById('sonBaslik').textContent=(oyuncu?oyuncu.ad+' · ':'')+(neden==='yanlis'?'❌ 3 yanlış hakkı bitti!':kalan<=0?'⏰ Süre bitti!':'🏁 Bütün harfler bitti!');\n  document.getElementById('yildiz').textContent='★'.repeat(yz)+'☆'.repeat(3-yz);\n  document.getElementById('ozet').innerHTML=`<b style=\"color:#4ADE80\">${d} doğru</b> · <b style=\"color:#F87171\">${y} yanlış</b> · <b style=\"color:#CBD5E1\">${b} cevapsız</b> · ${n} harf`;\n  document.getElementById('liste').innerHTML=SORULAR.map((q,i)=>{const s=durum[i];const r=s==='d'?'#16A34A':s==='y'?'#DC2626':'#475569';return `<div><b style=\"background:${r}\">${q[0]}</b><strong>${q[3]}</strong> — ${q[2]}</div>`}).join('');\n  goster('sonuc');if(d>=12)konfeti(260);kayitYaz({t:Date.now(),sinif:sinifNo>=0?LISTE[sinifNo].ad:'',ad:oyuncu?oyuncu.ad:'',d,yn:y,y:yz});d>=18?cal('zafer'):d>=12?(cal('dogru'),alkis(2.5,.4)):cal('bitis');oyuncu=null;sinifCiz()}\ndocument.addEventListener('keydown',e=>{if(!document.getElementById('oyun').classList.contains('aktif'))return;const k=e.key.toLocaleUpperCase('tr');if(e.key==='1'||k==='A')cevap(0);else if(e.key==='2'||k==='B')cevap(1);else if(e.key===' '){e.preventDefault();pas()}else if(e.key==='p'||e.key==='P')duraklat()});\n</script></body></html>\n";
